import os, shutil, hashlib
from pathlib import Path

root = Path('.')
src_root = root/'Unorganized'

# destination map from current tree excluding Unorganized
name_to_paths = {}
for dp, dns, fns in os.walk(root):
    p = Path(dp)
    if '.git' in p.parts:
        continue
    if p == src_root or src_root in p.parents:
        continue
    name_to_paths.setdefault(p.name, []).append(p)

prefer = {
    'Reactor-Cooling': Path('Energy-and-Power/Reactor-Cooling')
}

def file_hash(path: Path):
    h = hashlib.sha256()
    with path.open('rb') as f:
        for chunk in iter(lambda: f.read(1024*1024), b''):
            h.update(chunk)
    return h.hexdigest()

moved=0
dedup_removed=0
renamed_conflicts=0
unmapped=[]

for top in sorted([p for p in src_root.iterdir() if p.is_dir()], key=lambda p:p.name.lower()):
    cands = name_to_paths.get(top.name, [])
    if not cands:
        unmapped.append(top.name)
        continue
    if top.name in prefer:
        dest_root = prefer[top.name]
    elif len(cands)==1:
        dest_root = cands[0]
    else:
        dest_root = sorted(cands, key=lambda p: len(p.parts))[0]

    for dp, dns, fns in os.walk(top):
        dp = Path(dp)
        rel = dp.relative_to(top)
        out_dir = dest_root/rel
        out_dir.mkdir(parents=True, exist_ok=True)
        for fn in fns:
            src = dp/fn
            dst = out_dir/fn
            if not dst.exists():
                shutil.move(str(src), str(dst))
                moved += 1
                continue

            # if duplicate content, remove source copy
            try:
                same = (src.stat().st_size == dst.stat().st_size and file_hash(src)==file_hash(dst))
            except Exception:
                same = False
            if same:
                src.unlink()
                dedup_removed += 1
                continue

            # name conflict with different content: move with suffix
            stem = dst.stem
            suf = dst.suffix
            i = 1
            while True:
                cand = out_dir / f"{stem} (from Unorganized {i}){suf}"
                if not cand.exists():
                    shutil.move(str(src), str(cand))
                    renamed_conflicts += 1
                    break
                i += 1

# cleanup empties
for dp, dns, fns in os.walk(src_root, topdown=False):
    p = Path(dp)
    if p == src_root:
        continue
    try:
        p.rmdir()
    except OSError:
        pass

remaining_files = sum(len(fns) for _,_,fns in os.walk(src_root))
remaining_dirs = [p for p in src_root.iterdir() if p.is_dir()]
print(f"moved={moved}")
print(f"dedup_removed={dedup_removed}")
print(f"renamed_conflicts={renamed_conflicts}")
print('unmapped=' + (', '.join(unmapped) if unmapped else 'none'))
print(f"remaining_files={remaining_files}")
print(f"remaining_top_dirs={len(remaining_dirs)}")
for p in remaining_dirs[:30]:
    print('LEFT_DIR', p.name)
